function normalizeAndroidId(rawId) {
  if (!rawId) return ''
  let s = String(rawId).trim()
  if (!s) return ''
  // 16 位十六進位 → 直接轉小寫
  if (/^[0-9a-fA-F]{16}$/.test(s)) {
    return s.toLowerCase()
  }
  // UUID 8-4-4-4-12 → 統一大寫 → SHA-256 → 取前 16 位小寫
  if (/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(s)) {
    return sha256Hex(s.toUpperCase()).slice(0, 16)
  }
  // 其他格式 → 統一 SHA-256 → 取前 16 位小寫
  return sha256Hex(s).slice(0, 16)
}

let _aidTold = false

function getAndroidId(_) {
  let { source, java } = _ || this
  let androidId = ''
  let cached = source.get('androidId')
  if (cached) {
    androidId = normalizeAndroidId(String(cached))
  }
  if (!androidId) {
    let raw = ''
    try { raw = java.androidId() } catch (e) { try { java.log('androidId 不可用：' + e.message) } catch (_) {} }
    if (!raw) {
      try { raw = java.deviceID() } catch (e) { try { java.log('deviceID 不可用：' + e.message) } catch (_) {} }
    }
    androidId = normalizeAndroidId(raw)
    if (androidId) {
      source.put('androidId', androidId)
      if (!_aidTold) {
        _aidTold = true
        try {
          java.longToast('\nℹ️ 设备ID诊断(只弹一次)\n拿到原始值：' + (raw || '【空】') + '\n归一化后：' + androidId + '\n若原始值为空 = App 没给设备ID,接口会认成新设备')
        } catch (e) {}
      }
    } else if (!_aidTold) {
      _aidTold = true
      try { java.longToast('\n⚠️ 设备ID诊断(只弹一次)\n这台设备拿不到任何 ID\nx-android-id 将发空值,接口可能当匿名设备处理') } catch (e) {}
    }
  }
  return androidId
}
function getApiUrl(path, data, _) {
  let { source } = _ || this
  // 上游 v20260930 改叫 aid,旧版(和你已存的数据)叫 account_id —— 两个都发,服务端认哪个都不亏
  let aid = String(source.get('aid') || source.get('account_id') || '0') || '0'
  data.aid = aid
  data.account_id = aid
  let hostIndex = String(source.get('hostIndex') || '')
  if (hostIndex && hostIndex != 'null') {
    data.hostIndex = hostIndex
  }
  data = Object.entries(data).map(v => encodeURIComponent(v[0]) + '=' + encodeURIComponent(v[1] == null ? '' : v[1])).join('&')
  let androidId = getAndroidId(_)
  let option = {
    method: "GET", headers: {
      'authorization': `Bearer ${source.getVariable()}`,
      'x-android-id': androidId
    }
  }
  let url = api + path + '?' + data + ',' + JSON.stringify(option)
  return url
}
function requestApiUrl(path, data, _) {
  // 偶发空响应(服务器断连/CDN 抖动)会让整条规则直接崩,这里空响应重试 1 次再放弃
  let res = null
  let lastErr = '未知错误'
  for (let attempt = 0; attempt < 2; attempt++) {
    let t0 = Date.now()
    try {
      let url = getApiUrl(path, data, _)
      let body = _.java.ajax(url)
      if (body && String(body).trim() !== '') {
        res = JSON.parse(body)
        break
      }
      lastErr = '服务器返回空响应'
    } catch (e) {
      lastErr = e.message
    }
    let spent = Date.now() - t0
    // 只在"快速失败"时重试:几十毫秒就断 = 服务器直接断连,重试有意义;
    // 慢到几秒 = 超时,立刻重试只会把等待翻倍(实测会把 5.8s 拖成 11.6s),不重试。
    if (attempt === 0) {
      if (spent > 2500) {
        lastErr = lastErr + '(耗时' + spent + 'ms,判定为超时,不再重试)'
        break
      }
      try { _.java.log(`请求 ${path} ${lastErr},重试一次`) } catch (_) {}
    }
  }
  if (res === null) {
    try { _.java.longToast(`\n❌请求 ${path} 失败：${lastErr}\n请检查网络/切换 API 域名`) } catch (_) {}
    try { _.java.log(`请求共享接口${path}异常：` + lastErr) } catch (_) {}
    return null
  }
  if (res.error) {
    let _hint = ''
    if (res.code == 401) _hint = '\n👉 token 无效/已过期(有效期 3 天),去登录界面重新「获取token」并保存'
    else if (res.code == 403) _hint = '\n👉 无权访问,该接口需要登录或已切到会员账号'
    try { _.java.longToast(`\n操作失败，code${res.code}：\n${res.error}${_hint}`) } catch (_) {}
  }
  if (res.data) {
    return res.data
  }
  return null
}
